def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    g = np.array(grid)
    H, W = g.shape

    # Find the mirror line: the color that appears in the most rows
    from collections import Counter
    color_row_counts = Counter()
    for c in range(1, 10):
        count = 0
        for r in range(H):
            if c in g[r]:
                count += 1
        if count > 0:
            color_row_counts[c] = count
    mirror_color = color_row_counts.most_common(1)[0][0]

    # Find mirror column
    mirror_col = None
    for c in range(W):
        col = g[:, c]
        if np.all(col == mirror_color):
            mirror_col = c
            break
    if mirror_col is None:
        best_col, best_count = 0, -1
        for c in range(W):
            cnt = np.sum(g[:, c] == mirror_color)
            if cnt > best_count:
                best_count = cnt
                best_col = c
        mirror_col = best_col

    result = g.copy()

    for r in range(H):
        left = g[r, :mirror_col].tolist()
        right = g[r, mirror_col+1:].tolist()

        # Determine if objects are on left or right
        left_has = any(v != 0 and v != mirror_color for v in left)
        right_has = any(v != 0 and v != mirror_color for v in right)

        if not left_has and not right_has:
            continue

        if left_has and not right_has:
            source = [v for v in left if v != 0 and v != mirror_color]
            side_len = W - mirror_col - 1
            side = list(result[r, mirror_col+1:].tolist())
        elif right_has and not left_has:
            source = [v for v in right if v != 0 and v != mirror_color]
            side_len = mirror_col
            side = list(result[r, :mirror_col].tolist())
        else:
            continue

        if not source:
            continue

        # Determine pattern
        colors_in_source = list(set(source))

        if len(colors_in_source) == 1:
            color = colors_in_source[0]
            width = len(source)
            pattern = [color if i % width == 0 else 0 for i in range(side_len)]
        else:
            # Multi-color: find edge color (last in source) and other color
            edge_color = source[-1]
            # Edge block width (contiguous from end)
            edge_w = 1
            for i in range(len(source)-2, -1, -1):
                if source[i] == edge_color:
                    edge_w += 1
                else:
                    break
            # Other color and its width
            other_color = source[0]
            if other_color == edge_color:
                other_color = [c for c in colors_in_source if c != edge_color][0]
            other_w = 1
            for i in range(1, len(source)):
                if source[i] == other_color:
                    other_w += 1
                else:
                    break

            pattern = []
            for i in range(side_len):
                if i % edge_w == 0:
                    pattern.append(edge_color)
                elif i % other_w == 0:
                    pattern.append(other_color)
                else:
                    pattern.append(0)

        # Place pattern
        if left_has and not right_has:
            result[r, mirror_col+1:mirror_col+1+side_len] = pattern
        elif right_has and not left_has:
            result[r, mirror_col-side_len:mirror_col] = pattern

    return result.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    g = np.array(grid)
    H, W = g.shape

    # Find mirror column: column with most occurrences of a single non-zero color
    best_mirror_col = 0
    best_mirror_color = 1
    best_count = -1
    for c in range(W):
        for color in range(1, 10):
            cnt = int(np.sum(g[:, c] == color))
            if cnt > best_count:
                best_count = cnt
                best_mirror_col = c
                best_mirror_color = color
    mirror_col = best_mirror_col
    mirror_color = best_mirror_color

    result = g.copy()

    for r in range(H):
        if g[r, mirror_col] != mirror_color:
            continue

        left = g[r, :mirror_col].tolist()
        right = g[r, mirror_col + 1:].tolist()

        left_has = any(v != 0 for v in left)
        right_has = any(v != 0 for v in right)

        if not left_has and not right_has:
            continue

        if left_has and not right_has:
            # Find contiguous non-zero block closest to mirror (rightmost)
            nonzero_pos = [i for i, v in enumerate(left) if v != 0]
            if not nonzero_pos:
                continue
            rightmost = nonzero_pos[-1]
            leftmost = rightmost
            for i in range(rightmost - 1, -1, -1):
                if left[i] != 0:
                    leftmost = i
                else:
                    break
            obj = left[leftmost:rightmost + 1]
            side_len = len(right)
        elif right_has and not left_has:
            # Find contiguous non-zero block closest to mirror (leftmost)
            nonzero_pos = [i for i, v in enumerate(right) if v != 0]
            if not nonzero_pos:
                continue
            leftmost = nonzero_pos[0]
            rightmost = leftmost
            for i in range(leftmost + 1, len(right)):
                if right[i] != 0:
                    rightmost = i
                else:
                    break
            obj = right[leftmost:rightmost + 1]
            side_len = len(left)
        else:
            continue

        if not obj:
            continue

        colors_in_obj = list(set(obj))

        if len(colors_in_obj) == 1:
            color = colors_in_obj[0]
            width = len(obj)
            pattern = [color if i % width == 0 else 0 for i in range(side_len)]
        else:
            # Multi-color: edge = closest to mirror (last in obj)
            edge_color = obj[-1]
            edge_w = 1
            for i in range(len(obj) - 2, -1, -1):
                if obj[i] == edge_color:
                    edge_w += 1
                else:
                    break
            # Other color = farthest from mirror (first in obj)
            other_color = obj[0]
            other_w = 1
            for i in range(1, len(obj)):
                if obj[i] == other_color:
                    other_w += 1
                else:
                    break

            pattern = []
            for i in range(side_len):
                if i % edge_w == 0:
                    pattern.append(edge_color)
                elif i % other_w == 0:
                    pattern.append(other_color)
                else:
                    pattern.append(0)

        if left_has and not right_has:
            result[r, mirror_col + 1:mirror_col + 1 + side_len] = pattern
        elif right_has and not left_has:
            result[r, mirror_col - side_len:mirror_col] = pattern

    return result.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return grid

    rows = len(grid)
    cols = len(grid[0])
    result = [row[:] for row in grid]

    # Find background color (most common)
    from collections import Counter
    color_count = Counter()
    for r in range(rows):
        for c in range(cols):
            color_count[grid[r][c]] += 1
    bg = color_count.most_common(1)[0][0]

    # Find horizontal bar: row with most non-bg cells
    h_row = -1
    h_max = 0
    for r in range(rows):
        cnt = sum(1 for c in range(cols) if grid[r][c] != bg)
        if cnt > h_max:
            h_max = cnt
            h_row = r

    if h_row == -1:
        return result

    # Collect vertical bars (color, col, top, bottom)
    seen = set()
    for c in range(cols):
        color = grid[h_row][c]
        if color == bg or (h_row, c) in seen:
            continue
        # Trace vertically
        top = h_row
        while top - 1 >= 0 and grid[top - 1][c] == color:
            top -= 1
        bottom = h_row
        while bottom + 1 < rows and grid[bottom + 1][c] == color:
            bottom += 1
        seen.add((h_row, c))
        seen.add((top, c))
        seen.add((bottom, c))
        for r in range(top, bottom + 1):
            seen.add((r, c))

        ext = min(h_row - top, bottom - h_row)
        # Store: (color, col, center_row, ext)
        if (color, c) not in [(s[0], s[1]) for s in seen]:
            pass
        # We need a different data structure
        break

    # Better approach: collect bars
    bars = []  # (color, col, ext)
    used_cols = set()
    for c in range(cols):
        if c in used_cols:
            continue
        color = grid[h_row][c]
        if color == bg:
            continue
        top = h_row
        while top - 1 >= 0 and grid[top - 1][c] == color:
            top -= 1
        bottom = h_row
        while bottom + 1 < rows and grid[bottom + 1][c] == color:
            bottom += 1
        ext = min(h_row - top, bottom - h_row)
        bars.append((color, c, ext))
        used_cols.add(c)

    if not bars:
        return result

    # Reverse extensions
    old_exts = [b[2] for b in bars]
    new_exts = old_exts[::-1]

    # Apply changes
    for i, (color, c, old_ext) in enumerate(bars):
        new_ext = new_exts[i]
        if old_ext == new_ext:
            continue
        if new_ext < old_ext:
            # Remove tips
            for r in list(range(h_row - old_ext, h_row - new_ext)) + \
                      list(range(h_row + new_ext + 1, h_row + old_ext + 1)):
                if 0 <= r < rows:
                    result[r][c] = bg
        else:
            # Extend: fill new cells
            # First, clear old extent
            for r in list(range(h_row - old_ext, h_row + old_ext + 1)):
                if 0 <= r < rows:
                    result[r][c] = bg
            # Set new extent
            for r in range(h_row - new_ext, h_row + new_ext + 1):
                if 0 <= r < rows:
                    result[r][c] = color

    return result

def transform(grid: list[list[int]]) -> list[list[int]]:
    from collections import Counter

    rows = len(grid)
    cols = len(grid[0])
    result = [row[:] for row in grid]

    # Step 1: Find background color (most common)
    color_count = Counter()
    for r in range(rows):
        for c in range(cols):
            color_count[grid[r][c]] += 1
    bg = color_count.most_common(1)[0][0]

    # Step 2: Find horizontal bar row (most non-bg cells)
    bar_row = -1
    max_nonbg = 0
    for r in range(rows):
        cnt = sum(1 for c in range(cols) if grid[r][c] != bg)
        if cnt > max_nonbg:
            max_nonbg = cnt
            bar_row = r

    # Step 3: Find bar color (most common non-bg in bar row)
    row_colors = Counter()
    for c in range(cols):
        if grid[bar_row][c] != bg:
            row_colors[grid[bar_row][c]] += 1
    bar_color = row_colors.most_common(1)[0][0]

    # Step 4: Find vertical bars and their above extensions
    bars = []  # (col, color, above_ext)
    for c in range(cols):
        if grid[bar_row][c] == bg or grid[bar_row][c] == bar_color:
            continue
        color = grid[bar_row][c]
        top = bar_row
        while top - 1 >= 0 and grid[top - 1][c] == color:
            top -= 1
        above = bar_row - top
        bars.append((c, color, above))

    # Step 5: Sort above extensions
    sorted_above = sorted(b[2] for b in bars)

    # Step 6: Apply - clear old, set new symmetric extensions
    for i, (c, color, old_above) in enumerate(bars):
        new_above = sorted_above[i]
        # Clear all cells in this column matching the bar color (except bar row)
        for r in range(rows):
            if r != bar_row and grid[r][c] == color:
                result[r][c] = bg
        # Set new symmetric extent
        for r in range(bar_row - new_above, bar_row + new_above + 1):
            if r != bar_row and 0 <= r < rows:
                result[r][c] = color

    return result

from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    rows = len(grid)
    cols = len(grid) if rows > 0 else 0
    if rows == 0 or cols == 0:
        return [list(row) for row in grid]

    result = [list(row) for row in grid]

    # Step 1: Find 0-cells NOT reachable from boundary (using non-0 as walls)
    visited = [[False] * cols for _ in range(rows)]
    queue = deque()

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0 and (r == 0 or r == rows-1 or c == 0 or c == cols-1):
                queue.append((r, c))
                visited[r][c] = True

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc] and grid[nr][nc] == 0:
                visited[nr][nc] = True
                queue.append((nr, nc))

    # Step 2: Find 1-cells that ARE reachable from boundary (using 1 as wall)
    visited2 = [[False] * cols for _ in range(rows)]
    queue2 = deque()

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 1 and (r == 0 or r == rows-1 or c == 0 or c == cols-1):
                queue2.append((r, c))
                visited2[r][c] = True

    while queue2:
        r, c = queue2.popleft()
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and not visited2[nr][nc] and grid[nr][nc] != 1:
                visited2[nr][nc] = True
                queue2.append((nr, nc))

    # Apply changes:
    # Fill enclosed 0-cells with 1
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0 and not visited[r][c]:
                result[r][c] = 1

    # Remove exposed 1-cells
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1 and visited2[r][c]:
                result[r][c] = 0

    return result

