    # Step 1: BFS from boundary through 0-cells (non-zero = wall)
    visited = [[False] * cols for _ in range(rows)]
    queue = deque()

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0 and (r == 0 or r == rows-1 or c == 0 or c == cols-1):
                queue.append((r, c))
                visited[r][c] = True

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc] and grid[nr][nc] == 0:
                visited[nr][nc] = True
                queue.append((nr, nc))

    # Step 2: BFS from boundary through non-1 cells (1 = wall)
    visited2 = [[False] * cols for _ in range(rows)]
    queue2 = deque()

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 1 and (r == 0 or r == rows-1 or c == 0 or c == cols-1):
                queue2.append((r, c))
                visited2[r][c] = True

    while queue2:
        r, c = queue2.popleft()
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and not visited2[nr][nc] and grid[nr][nc] != 1:
                visited2[nr][nc] = True
                queue2.append((nr, nc))

    # Apply: Fill trapped 0-cells with 1, remove 1-cells in boundary region
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0 and not visited[r][c]:
                result[r][c] = 1
            elif grid[r][c] == 1 and visited2[r][c]:
                result[r][c] = 0

    return result

def transform(grid: list[list[int]]) -> list[list[int]]:
    rows = len(grid)
    cols = len(grid[0])

    # Find the two colors used
    color_set = set()
    for row in grid:
        for cell in row:
            color_set.add(cell)

    # Background = most common color overall (or on borders)
    from collections import Counter
    counter = Counter()
    for row in grid:
        for cell in row:
            counter[cell] += 1

    if len(color_set) <= 1:
        bg = list(color_set)[0] if color_set else 0
        fg = (bg + 1) % 10
    else:
        bg = counter.most_common(1)[0][0]
        fg = [c for c in color_set if c != bg][0]

    def get_val(i, j):
        """Mirror-wrap index into input grid"""
        ri = i if i < rows else 2 * rows - 1 - i
        cj = j if j < cols else 2 * cols - 1 - j
        return grid[ri][cj]

    out = [[0] * 20 for _ in range(20)]
    for i in range(20):
        for j in range(20):
            a = get_val(i, j)
            b = get_val(i + 1, j + 1)
            out[i][j] = fg if a != b else bg

    return out

