def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    W = len(grid[0])
    result = [row[:] for row in grid]

    def find_pattern(seq):
        n = len(seq)
        if n <= 1:
            return list(seq)
        best = None
        best_score = -1
        for p in range(1, n + 1):
            if n % p != 0:
                continue
            pattern = []
            for r in range(p):
                vals = [seq[i] for i in range(r, n, p)]
                counts = {}
                for v in vals:
                    counts[v] = counts.get(v, 0) + 1
                pattern.append(max(counts, key=lambda k: counts[k]))
            score = sum(1 for i in range(n) if seq[i] == pattern[i % p])
            if score > best_score:
                best_score = score
                best = pattern
        if best is None:
            return list(seq)
        return [best[i % len(best)] for i in range(n)]

    for i in range(H):
        j = 0
        while j < W:
            if grid[i][j] == 0:
                j += 1
                continue
            j2 = j
            while j2 < W and grid[i][j2] != 0:
                j2 += 1
            if j2 - j > 1:
                seq = [grid[i][k] for k in range(j, j2)]
                corrected = find_pattern(seq)
                for k in range(len(corrected)):
                    result[i][j + k] = corrected[k]
            j = j2

    return result

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    W = len(grid[0])
    result = [row[:] for row in grid]

    # Step 1: Find outer border color and grid lines
    border_color = grid[0][0]

    grid_line_rows = set()
    for i in range(H):
        if all(grid[i][j] == border_color for j in range(W)):
            grid_line_rows.add(i)

    grid_line_cols = set()
    for j in range(W):
        if all(grid[i][j] == border_color for i in range(H)):
            grid_line_cols.add(j)

    # Step 2: Identify blocks between grid lines
    glr_sorted = sorted(grid_line_rows)
    glc_sorted = sorted(grid_line_cols)

    row_blocks = []
    for i in range(len(glr_sorted) - 1):
        r1, r2 = glr_sorted[i], glr_sorted[i+1]
        if r2 - r1 > 1:
            row_blocks.append((r1 + 1, r2 - 1))

    col_blocks = []
    for j in range(len(glc_sorted) - 1):
        c1, c2 = glc_sorted[j], glc_sorted[j+1]
        if c2 - c1 > 1:
            col_blocks.append((c1 + 1, c2 - 1))

    # Step 3: Find cell border color
    from collections import Counter
    counter = Counter()
    for (r1, r2) in row_blocks:
        for (c1, c2) in col_blocks:
            # Check border pixels of the block
            for j in range(c1, c2 + 1):
                counter[grid[r1][j]] += 1
                counter[grid[r2][j]] += 1
            for i in range(r1, r2 + 1):
                counter[grid[i][c1]] += 1
                counter[grid[i][c2]] += 1

    # Exclude border_color, pick most common
    cell_border_color = None
    for color, count in counter.most_common():
        if color != border_color:
            cell_border_color = color
            break

    if cell_border_color is None:
        return result

    # Step 4: Find cells within each block
    cells = []
    for (br1, br2) in row_blocks:
        for (bc1, bc2) in col_blocks:
            # Find horizontal cell borders (rows that are all cell_border_color)
            h_borders = []
            for i in range(br1, br2 + 1):
                if all(grid[i][j] == cell_border_color for j in range(bc1, bc2 + 1)):
                    h_borders.append(i)

            # Find vertical cell borders (cols that are all cell_border_color)
            v_borders = []
            for j in range(bc1, bc2 + 1):
                if all(grid[i][j] == cell_border_color for i in range(br1, br2 + 1)):
                    v_borders.append(j)

            # Extract cells between borders
            for i in range(len(h_borders) - 1):
                cr1, cr2 = h_borders[i], h_borders[i+1]
                if cr2 - cr1 > 1:
                    for j in range(len(v_borders) - 1):
                        cc1, cc2 = v_borders[j], v_borders[j+1]
                        if cc2 - cc1 > 1:
                            cells.append((cr1 + 1, cr2 - 1, cc1 + 1, cc2 - 1))

    # Step 5: For each cell, find 2D repeating pattern and correct
    for (r1, r2, c1, c2) in cells:
        ch = r2 - r1 + 1  # content height
        cw = c2 - c1 + 1  # content width

        # Extract content
        content = [[grid[r1 + di][c1 + dj] for dj in range(cw)] for di in range(ch)]

        # Find best 2D pattern
        best_score = -1
        best_pattern = None
        for py in range(1, ch + 1):
            if ch % py != 0:
                continue
            for px in range(1, cw + 1):
                if cw % px != 0:
                    continue
                # Determine pattern by majority vote at each position
                pattern = []
                for ri in range(py):
                    row_pat = []
                    for ci in range(px):
                        vals = []
                        for dr in range(0, ch, 1):
                            if dr % py == ri:
                                for dc in range(0, cw, 1):
                                    if dc % px == ci:
                                        vals.append(content[dr][dc])
                        if vals:
                            vc = Counter(vals)
                            row_pat.append(vc.most_common(1)[0][0])
                        else:
                            row_pat.append(0)
                    pattern.append(row_pat)

                # Score
                score = 0
                for ri in range(ch):
                    for ci in range(cw):
                        if content[ri][ci] == pattern[ri % py][ci % px]:
                            score += 1

                if score > best_score:
                    best_score = score
                    best_pattern = (py, px, pattern)

        if best_pattern:
            py, px, pattern = best_pattern
            for ri in range(ch):
                for ci in range(cw):
                    result[r1 + ri][c1 + ci] = pattern[ri % py][ci % px]

    return result

