    H = len(grid)
    W = len(grid[0])
    result = [row[:] for row in grid]

    # Find inner left border: first column with constant non-zero value in all rows
    inner_left = None
    for c in range(W):
        val = grid[0][c]
        if val != 0 and all(grid[r][c] == val for r in range(H)):
            inner_left = c
            break

    if inner_left is None:
        return result

    target_col = inner_left + 1
    right_col = W - 1

    # Middle area for position lookup
    mid_start = target_col + 1
    mid_end = right_col  # inclusive

    # Find objects in left area (cols 0 to inner_left-1), grouped by color
    objects = {}  # color -> list of (r, c)
    for r in range(H):
        for c in range(inner_left):
            if grid[r][c] != 0:
                color = grid[r][c]
                if color not in objects:
                    objects[color] = []
                objects[color].append((r, c))

    # Find target rows from right border
    targets = {}  # color -> list of rows
    for r in range(H):
        color = grid[r][right_col]
        if color != 0:
            if color not in targets:
                targets[color] = []
            targets[color].append(r)

    # Find position columns from top row middle area
    positions = {}  # color -> list of cols
    for c in range(mid_start, mid_end + 1):
        color = grid[0][c]
        if color != 0:
            if color not in positions:
                positions[color] = []
            positions[color].append(c)

    # Collect all drawing operations
    draw_ops = []
    for color, cells in objects.items():
        if color not in targets or color not in positions:
            continue  # stays in place

        # Compute center
        rows = [r for r, c in cells]
        cols = [c for r, c in cells]
        center_r = (min(rows) + max(rows)) / 2.0
        center_c = (min(cols) + max(cols)) / 2.0

        for tr in targets[color]:
            for bc in positions[color]:
                draw_ops.append((tr, bc, color, cells, center_r, center_c))

    # Sort by target row descending (draw bottom first, top overwrites)
    draw_ops.sort(key=lambda x: -x[0])

    # Erase objects that have targets (from left area)
    for color, cells in objects.items():
        if color in targets and color in positions:
            for (r, c) in cells:
                result[r][c] = 0

    # Draw objects at target positions
    for tr, bc, color, cells, cr, cc in draw_ops:
        for (r, c) in cells:
            nr = tr + (r - round(cr))
            nc = bc + (c - round(cc))
            if 0 <= nr < H and 0 <= nc < W:
                result[nr][nc] = color

    return result

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    h = len(grid)
