            # Check horizontal: all same row, contiguous cols
            same_row = cells[cells[:, 0] == row]
            cols_h = sorted(set(same_row[:, 1].tolist()))
            if cols_h and (cols_h[-1] - cols_h[0] + 1) != len(cols_h):
                return False
            # Check vertical: all same col, contiguous rows
            same_col = cells[cells[:, 1] == c2]
            rows_v = sorted(set(same_col[:, 0].tolist()))
            if rows_v and (rows_v[-1] - rows_v[0] + 1) != len(rows_v):
                return False
        return True

    wall_color = None
    for c in range(1, 10):
        if np.any(g == c) and is_wall_color(c):
            wall_color = c
            break
    if wall_color is None:
        for c in range(1, 10):
            if np.any(g == c):
                wall_color = c
                break

    # Flood fill to find rectangular regions (non-wall cells)
    visited = np.zeros((h, w), dtype=bool)
    regions = []

    for r in range(h):
        for c in range(w):
            if g[r, c] != wall_color and not visited[r, c]:
                # BFS
                stack = [(r, c)]
                cells = []
                while stack:
                    cr, cc = stack.pop()
                    if cr < 0 or cr >= h or cc < 0 or cc >= w:
                        continue
                    if visited[cr, cc] or g[cr, cc] == wall_color:
                        continue
                    visited[cr, cc] = True
                    cells.append((cr, cc))
                    for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
                        stack.append((cr+dr, cc+dc))
                rmin = min(r for r, c in cells)
                rmax = max(r for r, c in cells)
                cmin = min(c for r, c in cells)
                cmax = max(c for r, c in cells)
                regions.append((rmin, rmax, cmin, cmax))

    # Determine output
    result = g.copy()

    for (rmin, rmax, cmin, cmax) in regions:
        region_cells = set()
        for r in range(rmin, rmax + 1):
            for c in range(cmin, cmax + 1):
                region_cells.add((r, c))

        # Background = most common non-wall color in region
        from collections import Counter
        counts = Counter()
        for (r, c) in region_cells:
            if g[r, c] != wall_color:
                counts[g[r, c]] += 1
        bg = counts.most_common(1)[0][0]

        # Find seeds (non-bg, non-wall cells)
        seeds = []
        for (r, c) in region_cells:
            if g[r, c] != wall_color and g[r, c] != bg:
                seeds.append((r, c, g[r, c]))

        if not seeds:
            # All background
            for (r, c) in region_cells:
                result[r, c] = bg
            continue

        # Find nearest corner for each seed
        def nearest_corner_dist(r, c, rmin, rmax, cmin, cmax):
            dl = max(c - cmin, r - rmin)
            dr = max(cmax - c, r - rmin)
            dl2 = max(c - cmin, rmax - r)
            dr2 = max(cmax - c, rmax - r)
            return min(dl, dr, dl2, dr2)

        # Determine which corner to use based on seeds
        corners = {
            'tl': (rmin, cmin),
            'tr': (rmin, cmax),
            'bl': (rmax, cmin),
            'br': (rmax, cmax)
        }

        # For each seed, find its distance from each corner
        # Use the corner that gives the minimum max-distance among seeds
        best_corner = 'tl'
        best_max_dist = float('inf')
        for cname, (cr, cc) in corners.items():
            max_d = 0
            for (r, c, col) in seeds:
                d = max(abs(r - cr), abs(c - cc))
                max_d = max(max_d, d)
            if max_d < best_max_dist:
                best_max_dist = max_d
                best_corner = cname

        cr, cc = corners[best_corner]

        # Assign each seed its distance
        seed_map = {}  # distance -> color
        for (r, c, col) in seeds:
            d = max(abs(r - cr), abs(c - cc))
            if d not in seed_map:
                seed_map[d] = col

        # Build cycle
        if seed_map:
            max_d = max(seed_map.keys())
            cycle_len = max_d + 1
            cycle = []
            for i in range(cycle_len):
                cycle.append(seed_map.get(i, bg))

            # Fill region with concentric rings
            for r in range(rmin, rmax + 1):
                for c in range(cmin, cmax + 1):
                    d = max(abs(r - cr), abs(c - cc))
                    result[r, c] = cycle[d % cycle_len]

    return result.tolist()

