            # Check vertical line through (r, cc)
            vert = [(r2, cc) for r2 in range(h) if (r2, cc) in cells]
            rows_v = sorted(r2 for r2, _ in vert)
            if rows_v and (rows_v[-1] - rows_v[0] + 1) != len(rows_v):
