    visited = np.zeros((h, w), dtype=bool)
    regions = []

    for sr in range(h):
        for sc in range(w):
            if g[sr, sc] != wall_color and not visited[sr, sc]:
                # BFS
                from collections import deque
                queue = deque([(sr, sc)])
                cells = []
                visited[sr, sc] = True
                while queue:
                    cr, cc = queue.popleft()
                    cells.append((cr, cc))
                    for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < h and 0 <= nc < w and not visited[nr, nc] and g[nr, nc] != wall_color:
                            visited[nr, nc] = True
                            queue.append((nr, nc))
                rmin = min(r for r, c in cells)
                rmax = max(r for r, c in cells)
                cmin = min(c for r, c in cells)
                cmax = max(c for r, c in cells)
                regions.append((rmin, rmax, cmin, cmax, cells))

    # Step 3: Process each region
