        seeds = []
        for (r, c) in cells:
            if g[r, c] != wall_color and g[r, c] != bg:
                seeds.append((r, c, int(g[r, c])))

        # Determine corner and cycle
        if seeds:
            corners = [(rmin, cmin), (rmin, cmax), (rmax, cmin), (rmax, cmax)]
            best_corner = None
            best_cycle = None
            best_score = float('inf')

            for cr, cc in corners:
                dists = {}
                for (r, c, col) in seeds:
                    d = max(abs(r - cr), abs(c - cc))
                    if d in dists:
                        continue  # conflict
                    dists[d] = col

                # Check if distances form consecutive sequence from 0
                if 0 not in dists:
                    continue
                max_d = max(dists.keys())
                valid = all(i in dists for i in range(max_d + 1))

                if valid:
                    cycle = [dists[i] for i in range(max_d + 1)]
                    score = max_d
                    if score < best_score:
                        best_score = score
                        best_corner = (cr, cc)
                        best_cycle = cycle

            if best_cycle is None:
                # Fallback: use first corner with any valid assignment
                for cr, cc in corners:
                    dists = {}
                    for (r, c, col) in seeds:
                        d = max(abs(r - cr), abs(c - cc))
                        if d not in dists:
                            dists[d] = col
                    max_d = max(dists.keys()) if dists else 0
                    best_cycle = [dists.get(i, bg) for i in range(max_d + 1)]
                    break
        else:
            best_cycle = [bg]

        # Fill region
        for (r, c) in cells:
            ring = min(r - rmin, rmax - r, c - cmin, cmax - c)
            color = best_cycle[ring % len(best_cycle)]
            result[r, c] = color

    return result.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    H = len(grid)
    W = len(grid[0]) if H > 0 else 0
    result = [row[:] for row in grid]

    def get_pixels(color):
        return [(r, c) for r in range(H) for c in range(W) if grid[r][c] == color]

    # Collect all non-background pixels
    non_bg = [(r, c) for r in range(H) for c in range(W) if grid[r][c] != 0]
    if not non_bg:
        return result

    colors = set(p[1] for p in non_bg)
    color_pixels = {c: get_pixels(c) for c in colors}

    # Group: for each scatter color, assign to the frame color with minimum avg distance
    assignments = {}
    for s_color, s_pixels in color_pixels.items():
        best_frame = None
        best_avg = float('inf')
        for f_color in colors:
            if f_color == s_color:
                continue
            f_pixels = color_pixels[f_color]
            if not f_pixels or not s_pixels:
                continue
            total_d = 0.0
            count = 0
            for sr, sc in s_pixels:
                min_d = min((sr - fr) ** 2 + (sc - fc) ** 2 for fr, fc in f_pixels)
                total_d += min_d
                count += 1
            avg_d = total_d / count
            if avg_d < best_avg:
                best_avg = avg_d
                best_frame = f_color
        if best_frame is not None:
            assignments[s_color] = best_frame

    # Determine frame colors and scatter colors
    frame_colors = set(assignments.values())
    scatter_colors = set(assignments.keys())

    # Clear scatter pixels
    for s_color in scatter_colors:
        for (r, c) in color_pixels[s_color]:
            result[r][c] = 0

    # Process each scatter color
    for s_color in scatter_colors:
        f_color = assignments[s_color]
        f_pixels = color_pixels[f_color]
        s_pixels = color_pixels[s_color]
        if not f_pixels or not s_pixels:
            continue

        # Frame bbox
        f_rows = [p[0] for p in f_pixels]
        f_cols = [p[1] for p in f_pixels]
        f_rmin, f_rmax = min(f_rows), max(f_rows)
        f_cmin, f_cmax = min(f_cols), max(f_cols)
        f_height = f_rmax - f_rmin + 1
        f_width = f_cmax - f_cmin + 1

        # Centroids
        s_row_avg = sum(p[0] for p in s_pixels) / len(s_pixels)
        s_col_avg = sum(p[1] for p in s_pixels) / len(s_pixels)
        f_row_avg = sum(p[0] for p in f_pixels) / len(f_pixels)
        f_col_avg = sum(p[1] for p in f_pixels) / len(f_pixels)

        d_row = s_row_avg - f_row_avg
        d_col = s_col_avg - f_col_avg

        # Determine dominant direction
        if abs(d_row) >= abs(d_col):
            if d_row < 0:
                side = 'top'
            else:
                side = 'bottom'
            orientation = 'vertical'
        else:
            if d_col < 0:
                side = 'left'
            else:
                side = 'right'
            orientation = 'horizontal'

        # Determine output count and alignment
        if orientation == 'vertical':
            out_count = len(set(p[0] for p in s_pixels))
            top_pixel = min(f_pixels, key=lambda p: (p[0], p[1]))
            out_col = top_pixel[1]
            if side == 'top':
                rows = list(range(f_rmin - 1, f_rmin - 1 - out_count, -1))
            else:
                rows = list(range(f_rmax + 1, f_rmax + 1 + out_count))
            for i in range(out_count):
                rr, cc = rows[i], out_col
                if 0 <= rr < H and 0 <= cc < W:
                    result[rr][cc] = s_color
        else:
            out_count = len(set(p[1] for p in s_pixels))
            if side == 'right':
                right_pixel = max(f_pixels, key=lambda p: (p[1], -p[0]))
                out_row = right_pixel[0]
                cols = list(range(f_cmax + 1, f_cmax + 1 + out_count))
            else:
                left_pixel = min(f_pixels, key=lambda p: (p[1], -p[0]))
                out_row = left_pixel[0]
                cols = list(range(f_cmin - 1, f_cmin - 1 - out_count, -1))
            for i in range(out_count):
                rr, cc = out_row, cols[i]
                if 0 <= rr < H and 0 <= cc < W:
                    result[rr][cc] = s_color

    return result

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    W = len(grid[0]) if H > 0 else 0
    result = [row[:] for row in grid]

    # Count pixels per color
    color_counts = {}
    for r in range(H):
        for c in range(W):
            if grid[r][c] != 0:
                color_counts[grid[r][c]] = color_counts.get(grid[r][c], 0) + 1

    if not color_counts:
        return result

    # Identify frame colors (top 2 most common)
    sorted_colors = sorted(color_counts.items(), key=lambda x: -x[1])
    if len(sorted_colors) < 2:
        return result
    frame_colors = set([sorted_colors[0][0], sorted_colors[1][0]])

    # Get pixels per frame color and compute bboxes
    frame_pixels = {}
    frame_bbox = {}
    for fc in frame_colors:
        pixels = [(r, c) for r in range(H) for c in range(W) if grid[r][c] == fc]
        frame_pixels[fc] = pixels
        rows = [p[0] for p in pixels]
        cols = [p[1] for p in pixels]
        frame_bbox[fc] = (min(rows), max(rows), min(cols), max(cols))

    # Find scatter pixels: non-frame colors inside a frame's bbox
    scatter_by_frame = {fc: [] for fc in frame_colors}
    for r in range(H):
        for c in range(W):
            v = grid[r][c]
            if v == 0 or v in frame_colors:
                continue
            for fc in frame_colors:
                rmin, rmax, cmin, cmax = frame_bbox[fc]
                if rmin <= r <= rmax and cmin <= c <= cmax:
                    scatter_by_frame[fc].append((r, c, v))

    # Clear scatter pixels from result
    for fc in frame_colors:
        for (r, c, v) in scatter_by_frame[fc]:
            result[r][c] = 0

    # Process each frame-scatter pair
    for fc in frame_colors:
        scatters = scatter_by_frame[fc]
        if not scatters:
            continue
        f_pixels = frame_pixels[fc]
        rmin, rmax, cmin, cmax = frame_bbox[fc]
        f_height = rmax - rmin + 1
        f_width = cmax - cmin + 1

        # Centroids
        f_row_avg = sum(p[0] for p in f_pixels) / len(f_pixels)
        f_col_avg = sum(p[1] for p in f_pixels) / len(f_pixels)
        s_row_avg = sum(p[0] for p in scatters) / len(scatters)
        s_col_avg = sum(p[1] for p in scatters) / len(scatters)

        # Determine direction
        if f_width > f_height:
            # Horizontal
            if s_col_avg > f_col_avg:
                direction = 'LEFT'
            else:
                direction = 'RIGHT'
            count = len(set(p[1] for p in scatters))
            if direction == 'RIGHT':
                ref_col = cmax
                ref_pixels = [(r, c) for (r, c) in f_pixels if c == cmax]
                ref_row = min(ref_pixels, key=lambda p: p[0])[0]
                positions = [(ref_row, cmax + 1 + i) for i in range(count)]
            else:
                ref_col = cmin
                ref_pixels = [(r, c) for (r, c) in f_pixels if c == cmin]
                ref_row = min(ref_pixels, key=lambda p: p[0])[0]
                positions = [(ref_row, cmin - 1 - i) for i in range(count)]
        else:
            # Vertical
            if s_row_avg > f_row_avg:
                direction = 'UP'
            else:
                direction = 'DOWN'
            count = len(set(p[0] for p in scatters))
            if direction == 'UP':
                ref_pixels = [(r, c) for (r, c) in f_pixels if r == rmin]
                ref_col = min(ref_pixels, key=lambda p: p[1])[1]
                positions = [(rmin - 1 - i, ref_col) for i in range(count)]
            else:
                ref_pixels = [(r, c) for (r, c) in f_pixels if r == rmax]
                ref_col = min(ref_pixels, key=lambda p: p[1])[1]
                positions = [(rmax + 1 + i, ref_col) for i in range(count)]

        # Place scatter-colored pixels
        for (rr, cc) in positions:
            if 0 <= rr < H and 0 <= cc < W:
                result[rr][cc] = scatters[0][2]  # scatter color

    return result

