    # Find all 0 cells
    zero_cells = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == 0]
    if not zero_cells:
        return [row[:] for row in grid]

    # Determine 0-block dimensions (assumed rectangular)
    rmin = min(r for r, c in zero_cells)
