    candidates = []
    for sr in range(rows - h + 1):
        for sc in range(cols - w + 1):
            # Check if all cells in this block are the same color (1 or 2)
            first = grid[sr][sc]
            if first not in (1, 2):
                continue
            valid = True
            for r in range(sr, sr + h):
                for c in range(sc, sc + w):
                    if grid[r][c] != first:
                        valid = False
                        break
                if not valid:
                    break
            if valid:
                candidates.append((sr, sc, first))

    if not candidates:
        return [row[:] for row in grid]

    def is_severable(sr, sc, color):
        """Check if removing this block keeps all remaining 1s connected."""
        blocked = set()
        for r in range(sr, sr + h):
            for c in range(sc, sc + w):
                blocked.add((r, c))

        # Collect all 1 cells not in the blocked area
        ones = set()
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == 1 and (r, c) not in blocked:
                    ones.add((r, c))

        if not ones:
            return True

        # BFS from first 1
        start = next(iter(ones))
        visited = set()
        queue = [start]
        visited.add(start)
        while queue:
            r, c = queue.pop()
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r+dr, c+dc
                if (nr, nc) in ones and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append((nr, nc))

        return len(visited) == len(ones)

    # Filter to severable candidates
    severable = [(sr, sc, col) for sr, sc, col in candidates if is_severable(sr, sc, col)]

    if not severable:
        # Fallback: use all candidates
        severable = candidates

    # Among severable, prefer 2s; if tie, prefer farthest from 0-block center
    def score(item):
        sr, sc, col = item
        center_r = sr + h / 2.0
        center_c = sc + w / 2.0
        zero_center_r = rmin + h / 2.0
        zero_center_c = cmin + w / 2.0
        dist = abs(center_r - zero_center_r) + abs(center_c - zero_center_c)
        # Prefer 2s (higher priority), then farther
        return (col == 2, dist)

    severable.sort(key=score, reverse=True)
    sr, sc, src_color = severable[0]

