    for r in range(sr, sr + h):
        for c in range(sc, sc + w):
            result[r][c] = 0

    return result

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return []

    rows = len(grid)
    cols = len(grid[0])

    # Count colors to find background
    color_count = {}
    for r in range(rows):
        for c in range(cols):
            color_count[grid[r][c]] = color_count.get(grid[r][c], 0) + 1
    bg = max(color_count, key=lambda k: color_count[k])

    # Find rows that are entirely background in the original grid
    all_bg_rows = []
    for r in range(rows):
        if all(grid[r][c] == bg for c in range(cols)):
            all_bg_rows.append(r)

    # Remove all-background rows
    kept_rows = [r for r in range(rows) if r not in set(all_bg_rows)]
    filtered = [grid[r][:] for r in kept_rows]
    filt_rows = len(filtered)

    # Find columns that are entirely background in the FULL original grid
    full_grid_bg_cols = []
    for c in range(cols):
        if all(grid[r][c] == bg for r in range(rows)):
            full_grid_bg_cols.append(c)

    # Find columns that are entirely background in the FILTERED grid
    filt_bg_cols = []
    for c in range(cols):
        if all(filtered[r][c] == bg for r in range(filt_rows)):
            filt_bg_cols.append(c)

    # Build blocks from full-grid bg columns (split the width)
    fg_blocks = []
    start = 0
    for c in full_grid_bg_cols:
        if c > start:
            fg_blocks.append((start, c - 1))
        start = c + 1
    if start < cols:
        fg_blocks.append((start, cols - 1))

    # Build blocks from filtered-grid bg columns
    f_blocks = []
    start = 0
    for c in filt_bg_cols:
        if c > start:
            f_blocks.append((start, c - 1))
        start = c + 1
    if start < cols:
        f_blocks.append((start, cols - 1))

    if len(fg_blocks) >= 2:
        # Multiple blocks from full-grid columns: take the second block
        c_start, c_end = fg_blocks[1]
        block = [row[c_start:c_end+1] for row in filtered]
    elif len(f_blocks) >= 2:
        # Multiple blocks from filtered-grid columns: take the first block
        c_start, c_end = f_blocks[0]
        block = [row[c_start:c_end+1] for row in filtered]
    else:
        block = [row[:] for row in filtered]

    # Crop to bounding box of non-background pixels
    min_r, max_r = filt_rows - 1, 0
    min_c, max_c = len(block[0]) - 1, 0
    for r in range(len(block)):
        for c in range(len(block[0])):
            if block[r][c] != bg:
                min_r = min(min_r, r)
                max_r = max(max_r, r)
                min_c = min(min_c, c)
                max_c = max(max_c, c)

    if min_r > max_r or min_c > max_c:
        # No non-background pixels found, return empty or single bg pixel
        return [[bg]]

    result = [block[r][min_c:max_c+1] for r in range(min_r, max_r+1)]
    return result

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    W = len(grid[0])

    # Find separator column (all 4s)
    sep_col = None
    for c in range(W):
        if all(grid[r][c] == 4 for r in range(H)):
            sep_col = c
            break

    # Find the 5 in the right side
    c5 = None
    for r in range(H):
        for c in range(sep_col + 1, W):
            if grid[r][c] == 5:
                c5 = c - sep_col - 1  # 0-based in right side
                break
        if c5 is not None:
            break

    # Find 3x3 symbol blocks on the left side
    symbols = []
    r = 0
    while r < H:
        if grid[r][0] != 0 or grid[r][1] != 0 or grid[r][2] != 0:
            row_group = r // 4
            # Check left block (cols 0-2)
            color = 0
            for dr in range(3):
                for dc in range(3):
                    if grid[r+dr][dc] != 0:
                        color = grid[r+dr][dc]
                        break
                if color:
                    break
            if color:
                symbols.append((row_group, 0, color))
            # Check right block (cols 4-6)
            color2 = 0
            for dr in range(3):
                for dc in range(3):
                    if grid[r+dr][4+dc] != 0:
                        color2 = grid[r+dr][4+dc]
                        break
                if color2:
                    break
            if color2:
                symbols.append((row_group, 1, color2))
            r += 4
        else:
            r += 1

    # Determine line properties
    def line_len(t):
        if t == 1: return 3
        if t == 2: return 2
        if t == 3: return 4
        if t == 6: return 2
        return 2

    def is_vertical(t):
        return t == 6

    # Sort: left side first (top to bottom), then right side (top to bottom)
    left_syms = sorted([s for s in symbols if s[1] == 0], key=lambda x: x[0])
    right_syms = sorted([s for s in symbols if s[1] == 1], key=lambda x: x[0])
    ordered = left_syms + right_syms

    # Create output
    output = [[0] * 7 for _ in range(H)]
    output[0][c5] = 5

    for (row_group, col_side, color) in ordered:
        line_row = (row_group - c5) * 3
        line_col = c5 + col_side

        length = line_len(color)

        if is_vertical(color):
            for i in range(length):
                rr = line_row + i
                if 0 <= rr < H and 0 <= line_col < 7:
                    output[rr][line_col] = color
        else:
            # Horizontal: try to place starting at line_col, clip if needed
            start_col = line_col
            while start_col + length > 7 and start_col > 0:
                start_col -= 1
            if start_col < 0:
                start_col = 0
            for i in range(length):
                cc = start_col + i
                if 0 <= cc < 7 and 0 <= line_row < H:
                    output[line_row][cc] = color

    return output

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    W = len(grid[0])

    # Find separator column (all 4s)
    sep_col = None
    for c in range(W):
        if all(grid[r][c] == 4 for r in range(H)):
            sep_col = c
            break

    # Find the 5 in the right side
    r5 = c5 = None
    for r in range(H):
        for c in range(sep_col + 1, W):
            if grid[r][c] == 5:
                r5 = r
                c5 = c - sep_col - 1  # 0-indexed in right side
                break
        if c5 is not None:
            break

    # Find 3x3 symbol blocks
    symbols = []
    r = 0
    while r < H:
        # Check if this is a symbol row (non-zero in first 3 cols or cols 4-6)
        left_has = any(grid[r+dr][dc] != 0 for dr in range(3) if r+dr < H for dc in range(3))
        right_has = any(grid[r+dr][4+dc] != 0 for dr in range(3) if r+dr < H for dc in range(3))

        if left_has or right_has:
            g = len(symbols)  # not quite, need row group
            row_group = r // 4

            if left_has:
                color = 0
                for dr in range(3):
                    for dc in range(3):
                        if r+dr < H and grid[r+dr][dc] != 0:
                            color = grid[r+dr][dc]
                            break
                    if color:
                        break
                symbols.append((row_group, 0, color))

            if right_has:
                color = 0
                for dr in range(3):
                    for dc in range(3):
                        if r+dr < H and grid[r+dr][4+dc] != 0:
                            color = grid[r+dr][4+dc]
                            break
                    if color:
                        break
                symbols.append((row_group, 1, color))

            r += 4
        else:
            r += 1

    # Sort: left side first (by row group), then right side (by row group)
    left_syms = sorted([s for s in symbols if s[1] == 0], key=lambda x: x[0])
    right_syms = sorted([s for s in symbols if s[1] == 1], key=lambda x: x[0])
    ordered = left_syms + right_syms

    # Line properties
    def line_len(t):
        if t == 1: return 3
        if t == 2: return 2
        if t == 3: return 4
        if t == 6: return 2
        return 2

    def is_vertical(t):
        return t == 6

    # Create output
    output = [[0] * 7 for _ in range(H)]
    output[r5][c5] = 5

    # Place symbols sequentially starting at row 1
    cur_row = 1
    for idx, (row_group, side, color) in enumerate(ordered):
        g = row_group
        length = line_len(color)

        # Compute column offset
        if side == 0:  # left
            offset = -2 + (2 * g if side == 0 else g - 1)
            start_col = c5 + offset
        else:  # right
            offset = 2 * g if side == 0 else g - 1
            start_col = c5 + offset

        # Clamp for horizontal
        if not is_vertical(color):
            while start_col + length > 7 and start_col > 0:
                start_col -= 1
            while start_col < 0:
                start_col += 1

        # Place the line
        if is_vertical(color):
            col = start_col
            if col < 0:
                col = 0
            if col > 6:
                col = 6
            for i in range(length):
                rr = cur_row + i
                if 0 <= rr < H:
                    output[rr][col] = color
        else:
            for i in range(length):
                cc = start_col + i
                if 0 <= cc < 7 and cur_row < H:
                    output[cur_row][cc] = color

        cur_row += length

    return output

import numpy as np
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    rows = len(grid)
    cols = len(grid[0])
    g = np.array(grid, dtype=int)

    # Find barrier: color with max non-bg count in rows spanning >= 60% width
    from collections import Counter
    best_color = None
    best_info = (0, 0, 0)  # count, span, minrow
    color_counts = Counter()
    color_rows = {}
    for r in range(rows):
        for c in range(cols):
            if g[r][c] != 0:
                color_counts[g[r][c]] += 1
                if g[r][c] not in color_rows:
                    color_rows[g[r][c]] = []
                color_rows[g[r][c]].append(r)

    for color, count in color_counts.items():
        rlist = color_rows[color]
        min_r, max_r = min(rlist), max(rlist)
        span = max_r - min_r + 1
        if span < 2:
            continue
        row_counts = Counter(rlist)
        max_span = sum(1 for r in range(min_r, max_r+1) if row_counts.get(r, 0) >= cols * 0.6)
        if max_span > best_info[0]:
            best_info = (max_span, span, min_r)
            best_color = color

    if best_color is None:
        return [list(r) for r in g]

    bmin_r, bmax_r = best_info[2], best_info[2] + best_info[1] - 1

    # Find gap columns in barrier
    gap_cols = {}
    for r in range(bmin_r, bmax_r + 1):
        for c in range(cols):
            if g[r][c] == 0:
                gap_cols.setdefault(r, []).append(c)

    if not gap_cols:
        return [list(r) for r in g]

    gap_col = min(
        (c for rs in gap_cols.values() for c in rs),
        key=lambda c: (min(r for r, cs in gap_cols.items() if c in cs), c)
    )

    top_gap_row = min(r for r, cs in gap_cols.items() if gap_col in cs)
    bot_gap_row = max(r for r, cs in gap_cols.items() if gap_col in cs)

    # Find shapes (connected components excluding barrier and background)
    visited = np.zeros((rows, cols), dtype=bool)
    shapes = []

    for r in range(rows):
        for c in range(cols):
            if g[r][c] != 0 and g[r][c] != best_color and not visited[r][c]:
                # BFS
                color = g[r][c]
                cells = []
                queue = deque([(r, c)])
                visited[r][c] = True
                while queue:
                    cr, cc = queue.popleft()
                    cells.append((cr, cc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc] and g[nr][nc] == color:
                            visited[nr][nc] = True
                            queue.append((nr, nc))
                min_cr, min_cc = min(cells)
                shape_list = [(cr-min_cr, cc-min_cc) for cr, cc in cells]
                side = 'above' if min_cr < bmin_r else 'below'
                shapes.append({'color': color, 'cells': shape_list,
                               'side': side, 'orig_row': min_cr, 'orig_col': min_cc})

    # Determine target column
    all_w = [max(c for _, c in s['cells']) + 1 for s in shapes]
    target_col = max(0, min(cols - min(all_w, default=cols),
                             gap_col - min(all_w, default=cols) // 2))

    result = g.copy()

    # Clear non-barrier, non-bg cells
    for r in range(rows):
        for c in range(cols):
            if result[r][c] != 0 and result[r][c] != best_color:
                result[r][c] = 0

    # Place shapes
    for side, gap_row, sign in [('above', top_gap_row, -1), ('below', bot_gap_row, 1)]:
        group = [s for s in shapes if s['side'] == side]
        group.sort(key=lambda s: s['orig_row'])
        offset = 0
        for shape in group:
            h = max(r for r, _ in shape['cells']) + 1
            for dr, dc in shape['cells']:
                nr = gap_row + sign * (offset + dr)
                nc = target_col + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if result[nr][nc] == 0 or result[nr][nc] != best_color:
                        result[nr][nc] = shape['color']
                    elif result[nr][nc] != best_color:
                        result[nr][nc] = shape['color']
            offset += h

    return [list(r) for r in result]

import numpy as np
from collections import deque, Counter

def transform(grid: list[list[int]]) -> list[list[int]]:
    rows = len(grid)
    cols = len(grid[0])
    g = np.array(grid, dtype=int)

    # Find barrier color and rows
    color_full_rows = {}
    for r in range(rows):
        row_counts = Counter(g[r].tolist())
        for color, cnt in row_counts.items():
            if color != 0 and cnt >= 0.6 * cols:
                color_full_rows.setdefault(color, set()).add(r)

    best_color, best_top, best_bot = None, 0, -1
    for color, rset in color_full_rows.items():
        rlist = sorted(rset)
        # Find longest contiguous block
        blocks = []
        start = rlist[0]
        for i in range(1, len(rlist)):
            if rlist[i] != rlist[i-1] + 1:
                blocks.append((start, rlist[i-1]))
                start = rlist[i]
        blocks.append((start, rlist[-1]))
        for s, e in blocks:
            if e - s + 1 > best_bot - best_top + 1:
                best_color = color
                best_top = s
                best_bot = e

    if best_color is None:
        return [list(r) for r in g]

    # Find gaps in barrier
    gaps = []
    for r in range(best_top, best_bot + 1):
        for c in range(cols):
            if g[r][c] == 0:
                gaps.append((r, c))

    if not gaps:
        return [list(r) for r in g]

    # Group gaps into channels
    gap_cols_sorted = sorted(set(c for _, c in gaps))
    channels = []
    for c in gap_cols_sorted:
        if channels and c - channels[-1][-1] <= 3:
            channels[-1].append(c)
        else:
            channels.append([c])

    channel_info = []
    for ch in channels:
        ch_gap_rows = [r for r, c in gaps if c in ch]
        min_gr, max_gr = min(ch_gap_rows), max(ch_gap_rows)
        barrier_mid = (best_top + best_bot) / 2.0
        gap_center = (min_gr + max_gr) / 2.0
        if gap_center <= barrier_mid:
            direction = 'up'
        else:
            direction = 'down'
        channel_info.append({'cols': ch, 'dir': direction, 'gap_center_row': gap_center})

    # Find shapes
    visited = np.zeros((rows, cols), dtype=bool)
    shapes = []
    for r in range(rows):
        for c in range(cols):
            if g[r][c] != 0 and g[r][c] != best_color and not visited[r][c]:
                color = g[r][c]
                cells = []
                queue = deque([(r, c)])
                visited[r][c] = True
                while queue:
                    cr, cc = queue.popleft()
                    cells.append((cr, cc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc] and g[nr][nc] == color:
                            visited[nr][nc] = True
                            queue.append((nr, nc))
                min_cr = min(cr for cr, _ in cells)
                min_cc = min(cc for _, cc in cells)
                max_cr = max(cr for cr, _ in cells)
                max_cc = max(cc for _, cc in cells)
                h = max_cr - min_cr + 1
                w = max_cc - min_cc + 1
                norm = [(cr - min_cr, cc - min_cc) for cr, cc in cells]
                shapes.append({
                    'color': color, 'cells': norm, 'h': h, 'w': w,
                    'orig_row': min_cr, 'center_col': (min_cc + max_cc) / 2.0
                })

    if not shapes:
        return [list(r) for r in g]

    # Assign shapes to channels
    ch_centers = [sum(ci['cols'])/len(ci['cols']) for ci in channel_info]
    for s in shapes:
        if len(channel_info) == 1:
            s['channel'] = 0
        else:
            dists = [abs(s['center_col'] - cc) for cc in ch_centers]
            s['channel'] = min(range(len(dists)), key=lambda i: dists[i])

    # Build result
    result = g.copy()
    for r in range(rows):
        for c in range(cols):
            if result[r][c] != 0 and result[r][c] != best_color:
                result[r][c] = 0

    # Place shapes in each channel
    for ci_idx, ci in enumerate(channel_info):
        ch_shapes = [s for s in shapes if s.get('channel') == ci_idx]
        if not ch_shapes:
            continue
        ch_shapes.sort(key=lambda s: (s['color'], s['orig_row']))

        max_w = max(s['w'] for s in ch_shapes)
        ch_center_col = sum(ci['cols']) / len(ci['cols'])
        target_col = int(round(ch_center_col - max_w / 2.0))
        target_col = max(0, min(cols - max_w, target_col))

        # Determine start position
        if ci['dir'] == 'up':
            # First shape bottom aligns with barrier top
            first_top = best_top - ch_shapes[0]['h'] + 1
        else:
            # First shape top aligns with barrier bottom
            first_top = best_bot

        prev_top = first_top
        for i, s in enumerate(ch_shapes):
            if i == 0:
                top = first_top
            else:
                prev = ch_shapes[i-1]
                top = prev_top + (prev['h'] + s['h']) // 2 - 1

            if ci['dir'] == 'up':
                top = max(0, min(best_top - s['h'] + 1, top))
            else:
                top = min(rows - s['h'], top)

            for dr, dc in s['cells']:
                nr = top + dr
                nc = target_col + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if result[nr][nc] == 0 or result[nr][nc] != best_color:
                        result[nr][nc] = s['color']
            prev_top = top

    return [list(r) for r in result]

def transform(grid: list[list[int]]) -> list[list[int]]:
    rows = len(grid)
    cols = len(grid[0])

    # Find the stamp (4s) - get its column range
    stamp_cols = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 4:
                stamp_cols.append(c)

    stamp_col_min = min(stamp_cols) if stamp_cols else 0
    stamp_col_max = max(stamp_cols) if stamp_cols else 0

    # Determine background color (most common on borders)
    from collections import Counter
    border_count = Counter()
    for c in range(cols):
        border_count[grid[0][c]] += 1
        border_count[grid[rows-1][c]] += 1
    for r in range(rows):
        border_count[grid[r][0]] += 1
        border_count[grid[r][cols-1]] += 1
    bg = border_count.most_common(1)[0][0]

    # Determine main color (most common non-background, non-stamp color)
    color_count = Counter()
    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]
            if val != bg and val != 4:
                color_count[val] += 1
    main_color = color_count.most_common(1)[0][0] if color_count else 0

    # Create output
    result = [row[:] for row in grid]

    for r in range(rows):
        if r % 2 == 0:
            if r % 6 == 0:
                # 3-row
                main_positions = [c for c in range(cols) if grid[r][c] == main_color]
                if main_positions:
                    left = min(main_positions)
                    right = max(main_positions)
                    for c in range(left, right + 1):
                        result[r][c] = 3
                for c in range(stamp_col_min, stamp_col_max + 1):
                    if result[r][c] != main_color:
                        result[r][c] = 3
            else:
                # 4-row
                for c in range(stamp_col_min, stamp_col_max + 1):
                    if grid[r][c] == main_color:
                        result[r][c] = 4
        else:
            # Odd row: remove main-color at stamp columns
            for c in range(stamp_col_min, stamp_col_max + 1):
                if grid[r][c] == main_color:
                    result[r][c] = bg

    return result

def transform(grid: list[list[int]]) -> list[list[int]]:
    from collections import Counter
    rows = len(grid)
    cols = len(grid[0])

    # Find stamp (4s) column range
    stamp_cols = set()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 4:
                stamp_cols.add(c)
    stamp_left = min(stamp_cols)
    stamp_right = max(stamp_cols)

    # Determine background (most common border value)
    border = Counter()
    for c in range(cols):
        border[grid[0][c]] += 1
        border[grid[rows-1][c]] += 1
    for r in range(rows):
        border[grid[r][0]] += 1
        border[grid[r][cols-1]] += 1
    bg = border.most_common(1)[0][0]

    # Determine main color (most common non-bg, non-4)
    cc = Counter()
    for r in range(rows):
        for c in range(cols):
            v = grid[r][c]
            if v != bg and v != 4:
                cc[v] += 1
    main = cc.most_common(1)[0][0]

    result = [row[:] for row in grid]

    for r in range(rows):
        if r % 2 == 0:
            if r % 6 == 0:
                # 3-row: find contiguous main-color groups, merge with stamp if touching
                groups = []
                c = 0
                while c < cols:
                    if grid[r][c] == main:
                        start = c
                        while c < cols and grid[r][c] == main:
                            c += 1
                        groups.append([start, c - 1])
                    else:
                        c += 1

                # Add stamp region
                all_regions = groups + [[stamp_left, stamp_right]]

                # Sort and merge overlapping/adjacent regions
                all_regions.sort()
                merged = [all_regions[0][:]]
                for s, e in all_regions[1:]:
                    if s <= merged[-1][1] + 1:
                        merged[-1][1] = max(merged[-1][1], e)
                    else:
                        merged.append([s, e])

                # Fill merged regions with 3
                for s, e in merged:
                    for c in range(s, e + 1):
                        result[r][c] = 3
            else:
                # 4-row: set main-color cells at stamp columns to 4
                for c in range(stamp_left, stamp_right + 1):
                    if grid[r][c] == main:
                        result[r][c] = 4
        else:
            # Odd row: remove main color at stamp columns
            for c in range(stamp_left, stamp_right + 1):
                if grid[r][c] == main:
                    result[r][c] = bg

    return result

