def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    W = len(grid[0])

    # Step 1: Convert 7s to 8,6,8
    out = [list(row) for row in grid]
    for r in range(H):
        c = 0
        while c < W:
            if out[r][c] == 7:
                c2 = c
                while c2 < W and out[r][c2] == 7:
                    c2 += 1
                length = c2 - c
                mid = c + length // 2
                for i in range(c, c2):
                    out[r][i] = 6 if i == mid else 8
                c = c2
            else:
                c += 1

    # Step 2: Identify wall rows
    wall_rows = set(r for r in range(H) if any(grid[r][c] == 8 for c in range(W)))

    # Step 3: Place 6s in wall rows from adjacent rows
    for r in wall_rows:
        for c in range(W):
            if out[r][c] != 0:
                if (r > 0 and out[r-1][c] == 6) or (r < H-1 and out[r+1][c] == 6):
                    out[r][c] = 6

    # Step 4: Place 3s with parity gate
    parity = (H + W + (1 if H % 4 != 0 else 0) + (1 if W % 4 == 3 else 0)) % 2
    for r in wall_rows:
        if (r + parity) % 2 == 0:
            zeros = [c for c in range(W) if grid[r][c] == 0]
            three_cols = {0, W - 1}
            for z in zeros:
                if z + 1 < W:
                    three_cols.add(z + 1)
            for c in three_cols:
                out[r][c] = 3

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    g = [list(row) for row in grid]
    H = len(g)
    W = len(g[0])

    # Identify wall rows (contain 8s in original)
    is_wall = [any(g[r][c] == 8 for c in range(W)) for r in range(H)]

    # Step 1: Convert 7-runs to 8,6,8 in all rows
    out = [list(row) for row in g]
    for r in range(H):
        c = 0
        while c < W:
            if out[r][c] == 7:
                end = c
                while end < W and out[r][end] == 7:
                    end += 1
                L = end - c
                mid = c + L // 2
                for i in range(c, end):
                    out[r][i] = 6 if i == mid else 8
                c = end
            else:
                c += 1

    # Step 2: Propagate 6s from content rows into wall rows
    for r in range(H):
        if is_wall[r]:
            for c in range(W):
                if out[r][c] != 0:
                    has_6 = False
                    if r > 0 and out[r-1][c] == 6:
                        has_6 = True
                    if r < H-1 and out[r+1][c] == 6:
                        has_6 = True
                    if has_6:
                        out[r][c] = 6

    # Step 3: Place 3s in wall rows
    for r in range(H):
        if not is_wall[r]:
            continue

        # Check if 8-runs touch both edges
        has_8_at_0 = any(g[rr][0] == 8 for rr in range(H))
        has_8_at_W = any(g[rr][W-1] == 8 for rr in range(H))

        # Check content rows (non-wall rows above and below)
        content_above = r-1 if r > 0 and not is_wall[r-1] else None
        content_below = r+1 if r < H-1 and not is_wall[r+1] else None

        left_content_zero = True
        right_content_zero = True
        if content_above is not None:
            if g[content_above][0] != 0:
                left_content_zero = False
            if g[content_above][W-1] != 0:
                right_content_zero = False
        if content_below is not None:
            if g[content_below][0] != 0:
                left_content_zero = False
            if g[content_below][W-1] != 0:
                right_content_zero = False
        if content_above is None and content_below is None:
            left_content_zero = False
            right_content_zero = False

        # Determine if 3s should appear at all
        can_left = left_content_zero
        can_right = right_content_zero

        if not can_left and not can_right:
            continue

        # Find 0-runs in the original wall row
        zero_runs = []
        c = 0
        while c < W:
            if g[r][c] == 0:
                start = c
                while c < W and g[r][c] == 0:
                    c += 1
                zero_runs.append((start, c-1))
            else:
                c += 1

        # Check if 8-run touches left edge (no 0 before first 8)
        touches_left = g[r][0] != 0
        touches_right = g[r][W-1] != 0

        # Place 3s
        # Left edge: if touches_left and can_left
        if touches_left and can_left:
            out[r][0] = 3
            # Also check if there's a 0-run right after col 0
            for (zs, ze) in zero_runs:
                if zs == 0:
                    # 0-run starts at 0, so col 0 is 0, not 8
                    # Don't place 3 here
                    if g[r][0] == 0:
                        out[r][0] = 0  # restore
                    break

        # Right edge: if touches_right and can_right
        if touches_right and can_right:
            out[r][W-1] = 3

        # Interior 3s at 0-run boundaries
        for (zs, ze) in zero_runs:
            # Left boundary of 0-run: position zs-1
            if zs > 0 and can_left:
                if out[r][zs-1] != 0:
                    out[r][zs-1] = 3
            # Right boundary of 0-run: position ze+1
            if ze < W-1 and can_right:
                if out[r][ze+1] != 0:
                    out[r][ze+1] = 3

    return out

from collections import Counter
from typing import List

def find_boundaries(arr, axis):
    """Find boundaries along given axis (0=rows, 1=cols)."""
    if axis == 0:
        length = len(arr)
        if length <= 1:
            return [0, length]
        get_vals = lambda i: [arr[i][j] for j in range(len(arr[0]))]
    else:
        length = len(arr[0])
        if length <= 1:
            return [0, length]
        get_vals = lambda i: [arr[j][i] for j in range(len(arr))]

    doms = []
    for i in range(length):
        c = Counter(get_vals(i))
        doms.append(c.most_common(1)[0][0])

    boundaries = [0]
    for i in range(1, length):
        if doms[i] != doms[i - 1]:
            boundaries.append(i)
    boundaries.append(length)
    return boundaries

def get_noise_color(block, default):
    """Get the mode of non-dominant pixels in a block."""
    counter = Counter()
    for row in block:
        for val in row:
            if val != default:
                counter[val] += 1
    if counter:
        return counter.most_common(1)[0][0]
    return default

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return []

    H = len(grid)
    W = len(grid[0])

    row_bounds = find_boundaries(grid, 0)
    col_bounds = find_boundaries(grid, 1)

    num_rb = len(row_bounds) - 1
    num_cb = len(col_bounds) - 1

    # Extract block info
    block_colors = [[0] * num_cb for _ in range(num_rb)]
    block_heights = []
    block_widths = []

    for i in range(num_rb):
        block_heights.append(row_bounds[i+1] - row_bounds[i])
    for j in range(num_cb):
        block_widths.append(col_bounds[j+1] - col_bounds[j])

    for i in range(num_rb):
        for j in range(num_cb):
            r1, r2 = row_bounds[i], row_bounds[i+1]
            c1, c2 = col_bounds[j], col_bounds[j+1]
            block = [grid[r][c1:c2] for r in range(r1, r2)]

            counter = Counter()
            for row in block:
                for val in row:
                    counter[val] += 1
            dominant = counter.most_common(1)[0][0]
            noise_color = get_noise_color(block, dominant)
            block_colors[i][j] = noise_color

    # Build transposed output
    # Output row group j has height = block_widths[j]
    # Output col group i has width = block_heights[i]
    # Output block (j, i) gets color block_colors[i][j]

    out_rows = W
    out_cols = H

    out = [[0] * out_cols for _ in range(out_rows)]

    out_row_bounds = [0]
    for j in range(num_cb):
        out_row_bounds.append(out_row_bounds[-1] + block_widths[j])

    out_col_bounds = [0]
    for i in range(num_rb):
        out_col_bounds.append(out_col_bounds[-1] + block_heights[i])

    for j in range(num_cb):
        for i in range(num_rb):
            r1, r2 = out_row_bounds[j], out_row_bounds[j+1]
            c1, c2 = out_col_bounds[i], out_col_bounds[i+1]
            color = block_colors[i][j]
            for r in range(r1, r2):
                for c in range(c1, c2):
                    out[r][c] = color

    return out

