def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return []

    H = len(grid)
    W = len(grid[0])

    THRESHOLD = 0.5

    def detect_row_bounds():
        if H == 1:
            return [0, 1]
        bounds = [0]
        for r in range(1, H):
            matches = sum(1 for c in range(W) if grid[r][c] == grid[r-1][c])
            if matches / W < THRESHOLD:
                bounds.append(r)
        bounds.append(H)
        return bounds

    def detect_col_bounds():
        if W == 1:
            return [0, 1]
        bounds = [0]
        for c in range(1, W):
            matches = sum(1 for r in range(H) if grid[r][c] == grid[r][c-1])
            if matches / H < THRESHOLD:
                bounds.append(c)
        bounds.append(W)
        return bounds

    row_bounds = detect_row_bounds()
    col_bounds = detect_col_bounds()

    num_rb = len(row_bounds) - 1
    num_cb = len(col_bounds) - 1

    # Row group color counters
    row_group_counter = []
    for i in range(num_rb):
        r1, r2 = row_bounds[i], row_bounds[i+1]
        counter = Counter()
        for r in range(r1, r2):
            for c in range(W):
                counter[grid[r][c]] += 1
        row_group_counter.append(counter)

    # Block dominant colors
    block_dom = [[0]*num_cb for _ in range(num_rb)]
    for i in range(num_rb):
        for j in range(num_cb):
            r1, r2 = row_bounds[i], row_bounds[i+1]
            c1, c2 = col_bounds[j], col_bounds[j+1]
            counter = Counter()
            for r in range(r1, r2):
                for c in range(c1, c2):
                    counter[grid[r][c]] += 1
            block_dom[i][j] = counter.most_common(1)[0][0]

    # Output colors: for transposed position (j,i), use mode of non-dominant colors in row group i
    out_color = [[0]*num_rb for _ in range(num_cb)]
    for j in range(num_cb):
        for i in range(num_rb):
            dom = block_dom[i][j]
            best = 0
            best_cnt = -1
            for color, cnt in row_group_counter[i].items():
                if color != dom and cnt > best_cnt:
                    best_cnt = cnt
                    best = color
            if best_cnt < 0:
                best = row_group_counter[i].most_common(1)[0][0]
            out_color[j][i] = best

    # Build transposed output
    out = [[0]*H for _ in range(W)]
    out_r = 0
    for j in range(num_cb):
        jh = col_bounds[j+1] - col_bounds[j]
        out_c = 0
        for i in range(num_rb):
            iw = row_bounds[i+1] - row_bounds[i]
            for dr in range(jh):
                for dc in range(iw):
                    out[out_r+dr][out_c+dc] = out_color[j][i]
            out_c += iw
        out_r += jh

    return out

