        val_positions = {}
        for c in range(W):
            if grid[r][c] != 0:
                v = grid[r][c]
                if v not in val_positions:
                    val_positions[v] = []
                val_positions[v].append(c)

        if not val_positions:
            continue

        # Determine period value (appears 2+ times) and target value
        period_val = None
        target_val = None
        if len(val_positions) == 1:
            # Only one value present
            v = list(val_positions.keys())[0]
            period_val = v
            target_val = v
        else:
            for v, pos in val_positions.items():
                if len(pos) >= 2:
                    period_val = v
                else:
                    target_val = v

        # Compute period from period_val positions
        pos = val_positions[period_val]
        if len(pos) >= 2:
            period = pos[1] - pos[0]
        else:
            period = 1

        if period <= 0:
            period = 1

        # Fill: from 0, step by period, up to W - period (inclusive)
        # This gives positions {0, P, 2P, ..., floor((W-P)/P)*P}
        fill_val = target_val
        c = 0
        while c <= W - period:
            result[r][c] = fill_val
            c += period

    return result

