        row = []
        for c in range(out_c0, out_c1):
            if band_start <= r <= band_end:
                row.append(grid[r + p][c])
            elif r < band_start:
                row.append(grid[r + p][c])
            else:
                row.append(grid[r - p][c])
        result.append(row)

    return result

import numpy as np
from collections import deque

def transform(grid):
    g = np.array(grid)
    rows, cols = g.shape
    visited = np.zeros_like(g, dtype=bool)

    comp_map = {}
    for r in range(rows):
        for c in range(cols):
            if g[r,c] != 0 and not visited[r,c]:
                color = g[r,c]
                comp = []
                queue = deque([(r,c)])
                visited[r,c] = True
                while queue:
                    cr, cc = queue.popleft()
                    comp.append((cr,cc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0<=nr<rows and 0<=nc<cols and not visited[nr,nc] and g[nr,nc]==color:
                            visited[nr,nc] = True
                            queue.append((nr,nc))
                comp_map.setdefault(color, []).append(comp)

    selected = {}
    for color, comps in comp_map.items():
        def bbox_area(comp):
            rs = [r for r,_ in comp]; cs = [c for _,c in comp]
            return (max(rs)-min(rs)+1) * (max(cs)-min(cs)+1)
        main = max(comps, key=bbox_area)
        selected[color] = set(main)

    result = g.copy()

    def cast_beam(sr, sc, dr, dc, color, cells, result, rows, cols):
        """Cast beam, bounce once at first blocker."""
        cr, cc = sr + dr, sc + dc
        while 0 <= cr < rows and 0 <= cc < cols:
            if result[cr,cc] != 0 and result[cr,cc] != color:
                # Bounce: perpendicular diagonal
                br, bc = -dc, dr
                br2, bc2 = cr + br, cc + bc
                while 0 <= br2 < rows and 0 <= bc2 < cols:
                    if result[br2,bc2] != 0 and result[br2,bc2] != color:
                        break
                    if (br2,bc2) not in cells:
                        result[br2,bc2] = color
                    br2 += br
                    bc2 += bc
                return
            if (cr,cc) not in cells:
                result[cr,cc] = color
            cr += dr
            cc += dc

    for color, cells in selected.items():
        rs = [r for r,_ in cells]; cs = [c for _,c in cells]
        min_r, max_r, min_c, max_c = min(rs), max(rs), min(cs), max(cs)
        h, w = max_r - min_r + 1, max_c - min_c + 1
        n = len(cells)

        if n == 3 and h == 2 and w == 2:
            # L-shape: diagonal from tip
            cell_set = cells
            tip = None
            for (r,c) in cell_set:
                nbrs = sum(1 for dr2,dc2 in [(-1,0),(1,0),(0,-1),(0,1)] if (r+dr2,c+dc2) in cell_set)
                if nbrs == 1:
                    tip = (r,c); break
            if tip:
                other = [cl for cl in cell_set if cl != tip]
                avg_r = sum(r for r,_ in other)/2
                avg_c = sum(c for _,c in other)/2
                dr = 1 if avg_r > tip[0] else (-1 if avg_r < tip[0] else 0)
                dc = 1 if avg_c > tip[1] else (-1 if avg_c < tip[1] else 0)
                cast_beam(tip[0], tip[1], dr, dc, color, cells, result, rows, cols)
        elif h == 1 and w >= 2:
            # Horizontal: vertical beam from center
            mid_c = min_c + w // 2
            up_dist = min_r + 1
            dn_dist = rows - max_r - 1
            if up_dist <= dn_dist:
                cast_beam(min_r, mid_c, -1, 0, color, cells, result, rows, cols)
            else:
                cast_beam(max_r, mid_c, 1, 0, color, cells, result, rows, cols)
        elif w == 1 and h >= 2:
            # Vertical: horizontal beam from center
            mid_r = min_r + h // 2
            lt_dist = min_c + 1
            rt_dist = cols - max_c - 1
            if lt_dist <= rt_dist:
                cast_beam(mid_r, min_c, 0, -1, color, cells, result, rows, cols)
            else:
                cast_beam(mid_r, max_c, 0, 1, color, cells, result, rows, cols)
        else:
            # 2x2 block or other: diagonal from corner
            dr = -1 if (min_r < rows - 1 - max_r) else 1
            dc = -1 if (min_c < cols - 1 - max_c) else 1
            sr = min_r if dr < 0 else max_r
            sc = min_c if dc < 0 else max_c
            cast_beam(sr, sc, dr, dc, color, cells, result, rows, cols)

    return result.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    rows = len(grid)
    cols = len(grid)

    sevens = set()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 7:
                sevens.add((r, c))

    if not sevens:
        return [row[:] for row in grid]

    candidate_4s = set()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] in (4, 7):
                candidate_4s.add((r, c))

    def is_valid_frame(r1, c1, r2, c2):
        if r2 <= r1 or c2 <= c1:
            return False
        for c in range(c1, c2 + 1):
            if (r1, c) not in candidate_4s or (r2, c) not in candidate_4s:
                return False
        for r in range(r1, r2 + 1):
            if (r, c1) not in candidate_4s or (r, c2) not in candidate_4s:
                return False
        return True

    valid_frames = []
    for r1 in range(rows):
        for r2 in range(r1 + 1, rows):
            for c1 in range(cols):
                for c2 in range(c1 + 1, cols):
                    if is_valid_frame(r1, c1, r2, c2):
                        valid_frames.append((r1, c1, r2, c2))

    def covers_sevens(f1, f2):
        for (r, c) in sevens:
            in_f1 = f1[0] <= r <= f1[2] and f1[1] <= c <= f1[3]
            in_f2 = f2[0] <= r <= f2[2] and f2[1] <= c <= f2[3]
            if not (in_f1 and in_f2):
                return False
        return True

    best_pair = None
    best_score = -1
    for i in range(len(valid_frames)):
        for j in range(i + 1, len(valid_frames)):
            f1, f2 = valid_frames[i], valid_frames[j]
            if not covers_sevens(f1, f2):
                continue
            # Count how many 4s are on each frame's border
            def border_count(f):
                r1, c1, r2, c2 = f
                count = 0
                for c in range(c1, c2 + 1):
                    if grid[r1][c] == 4: count += 1
                    if grid[r2][c] == 4: count += 1
                for r in range(r1 + 1, r2):
                    if grid[r][c1] == 4: count += 1
                    if grid[r][c2] == 4: count += 1
                return count

            score = border_count(f1) + border_count(f2)
            if score > best_score:
                best_score = score
                best_pair = (f1, f2)

    if best_pair is None:
        result = [row[:] for row in grid]
        for r in range(rows):
            for c in range(cols):
                if result[r][c] == 7:
                    result[r][c] = 4
        return result

    f1, f2 = best_pair
    if (f1[0], f1[1]) > (f2[0], f2[1]):
        f1, f2 = f2, f1

    def extract_frame(f):
        r1, c1, r2, c2 = f
        h = r2 - r1 + 1
        w = c2 - c1 + 1
        frame = [[1] * w for _ in range(h)]
        for i in range(h):
            for j in range(w):
                if i == 0 or i == h - 1 or j == 0 or j == w - 1:
                    frame[i][j] = 4
        return frame

    frame1 = extract_frame(f1)
    frame2 = extract_frame(f2)

    h1, w1 = len(frame1), len(frame1[0])
    h2, w2 = len(frame2), len(frame2[0])

    # Determine how to place them
    # Check relationships
    # Side by side with shared column: f1[3] == f2[1] and same rows
    # Top/bottom with shared row: f1[2] == f2[0] and same cols
    # Side by side adjacent: f1[3] + 1 == f2[1]
    # Top/bottom adjacent: f1[2] + 1 == f2[0]

    if f2[0] == f1[0] and f2[2] == f1[2]:
        # Same row span - side by side
        if f2[1] == f1[3]:
            # Shared column
            result = [row[:] for row in frame1]
            for i in range(h1):
                for j in range(1, w2):
                    result[i].append(frame2[i][j])
        else:
            # Gap or overlap - just concatenate
            result = [row[:] for row in frame1]
            for i in range(h1):
                for j in range(w2):
                    result[i].append(frame2[i][j])
    elif f2[1] == f1[1] and f2[3] == f1[3]:
        # Same col span - top/bottom
        if f2[0] == f1[2]:
            # Shared row
            result = [row[:] for row in frame1]
            for i in range(1, h2):
                result.append(frame2[i][:])
        else:
            # Adjacent
            result = [row[:] for row in frame1]
            for i in range(h2):
                result.append(frame2[i][:])
    else:
        # Diagonal or other - concatenate side by side
        max_h = max(h1, h2)
        result = []
        for i in range(max_h):
            row = []
            if i < h1:
                row.extend(frame1[i])
            else:
                row.extend([1] * w1)
            if i < h2:
                row.extend(frame2[i])
            else:
                row.extend([1] * w2)
            result.append(row)

    return result

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    rows = len(grid)
    cols = len(grid)

    # Replace 7s with 4s for analysis
    g = [[grid[r][c] if grid[r][c] != 7 else 4 for c in range(cols)] for r in range(rows)]

    # Find all maximal rectangles where the border is all 4s
    # A rectangle (r1,c1,r2,c2) has all-4 border if:
    # - All cells in row r1 from c1 to c2 are 4
    # - All cells in row r2 from c1 to c2 are 4
    # - All cells in col c1 from r1 to r2 are 4
    # - All cells in col c2 from r1 to r2 are 4

    def is_frame(r1, c1, r2, c2):
        if r2 <= r1 or c2 <= c1:
            return False
        for c in range(c1, c2 + 1):
            if g[r1][c] != 4 or g[r2][c] != 4:
                return False
        for r in range(r1, r2 + 1):
            if g[r][c1] != 4 or g[r][c2] != 4:
                return False
        return True

    # Find all frames
    frames = []
    for r1 in range(rows):
        for r2 in range(r1 + 1, rows):
            for c1 in range(cols):
                for c2 in range(c1 + 1, cols):
                    if is_frame(r1, c1, r2, c2):
                        frames.append((r1, c1, r2, c2))

    # Find the two "largest" frames that together cover all 7-positions
    # (after 7→4 replacement, the 7-positions should be on frame borders)

    seven_positions = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == 7]

    if not frames:
        # No frames found, just replace 7s with 4s
        return [[grid[r][c] if grid[r][c] != 7 else 4 for c in range(cols)] for r in range(rows)]

    # Find pairs of frames where both 7-positions are on the border of at least one frame
    def on_border(pos, frame):
        r, c = pos
        r1, c1, r2, c2 = frame
        if not (r1 <= r <= r2 and c1 <= c <= c2):
            return False
        return r == r1 or r == r2 or c == c1 or c == c2

    best_pair = None
    best_score = -1
    for i in range(len(frames)):
        for j in range(i + 1, len(frames)):
            f1, f2 = frames[i], frames[j]
            # Check if all 7-positions are on the border of f1 or f2
            ok = True
            for pos in seven_positions:
                if not (on_border(pos, f1) or on_border(pos, f2)):
                    ok = False
                    break
            if ok:
                # Score: prefer larger frames
                area1 = (f1[2]-f1[0]+1) * (f1[3]-f1[1]+1)
                area2 = (f2[2]-f2[0]+1) * (f2[3]-f2[1]+1)
                score = area1 + area2
                if score > best_score:
                    best_score = score
                    best_pair = (f1, f2)

    if best_pair is None:
        # Just replace 7s with 4s
        return [[grid[r][c] if grid[r][c] != 7 else 4 for c in range(cols)] for r in range(rows)]

    f1, f2 = best_pair
    # Extract the two frames and determine how to place them
    def extract_frame(frame):
        r1, c1, r2, c2 = frame
        h = r2 - r1 + 1
        w = c2 - c1 + 1
        result = [[1]*w for _ in range(h)]
        for i in range(h):
            for j in range(w):
                if i == 0 or i == h-1 or j == 0 or j == w-1:
                    result[i][j] = 4
                else:
                    result[i][j] = g[r1+i][c1+j]
        return result

    frame1 = extract_frame(f1)
    frame2 = extract_frame(f2)

    # Determine placement: check if they share a border in the input
    r1a, c1a, r2a, c2a = f1
    r1b, c1b, r2b, c2b = f2

    # Check adjacency
    # Side by side: c2a == c1b or c2a+1 == c1b (same row range)
    # Stacked: r2a == r1b or r2a+1 == r1b (same col range)
    # Overlapping: they share some cells

    # For now, place them based on their relative positions
    if r1a == r1b and c2a >= c1b:
        # Overlapping horizontally, same top - place side by side with overlap
        # Find the overlap
        overlap_c1 = max(c1a, c1b)
        overlap_c2 = min(c2a, c2b)
        overlap_w = overlap_c2 - overlap_c1 + 1 if overlap_c2 >= overlap_c1 else 0

        # Merge: take union
        min_r1 = min(r1a, r1b)
        max_r2 = max(r2a, r2b)
        min_c1 = min(c1a, c1b)
        max_c2 = max(c2a, c2b)

        h = max_r2 - min_r1 + 1
        w = max_c2 - min_c1 + 1
        result = [[1]*w for _ in range(h)]

        # Place frame1
        for i in range(r2a-r1a+1):
            for j in range(c2a-c1a+1):
                if frame1[i][j] == 4:
                    result[i + (r1a-min_r1)][j + (c1a-min_c1)] = 4

        # Place frame2
        for i in range(r2b-r1b+1):
            for j in range(c2b-c1b+1):
                if frame2[i][j] == 4:
                    result[i + (r1b-min_r1)][j + (c1b-min_c1)] = 4
                elif result[i + (r1b-min_r1)][j + (c1b-min_c1)] == 1:
                    result[i + (r1b-min_r1)][j + (c1b-min_c1)] = frame2[i][j]

        return result

    elif c1a == c1b and r2a >= r1b:
        # Overlapping vertically, same left - stack with overlap
        min_r1 = min(r1a, r1b)
        max_r2 = max(r2a, r2b)
        min_c1 = min(c1a, c1b)
        max_c2 = max(c2a, c2b)

        h = max_r2 - min_r1 + 1
        w = max_c2 - min_c1 + 1
        result = [[1]*w for _ in range(h)]

        for i in range(r2a-r1a+1):
            for j in range(c2a-c1a+1):
                if frame1[i][j] == 4:
                    result[i + (r1a-min_r1)][j + (c1a-min_c1)] = 4

        for i in range(r2b-r1b+1):
            for j in range(c2b-c1b+1):
                if frame2[i][j] == 4:
                    result[i + (r1b-min_r1)][j + (c1b-min_c1)] = 4
                elif result[i + (r1b-min_r1)][j + (c1b-min_c1)] == 1:
                    result[i + (r1b-min_r1)][j + (c1b-min_c1)] = frame2[i][j]

        return result

    else:
        # Side by side or stacked (no overlap)
        if r1a == r1b:
            # Side by side
            w = (c2a - c1a + 1) + (c2b - c1b + 1)
            h = max(r2a-r1a+1, r2b-r1b+1)
            result = [[1]*w for _ in range(h)]
            for i in range(r2a-r1a+1):
                for j in range(c2a-c1a+1):
                    result[i][j] = frame1[i][j]
            for i in range(r2b-r1b+1):
                for j in range(c2b-c1b+1):
                    result[i][j + (c2a-c1a+1)] = frame2[i][j]
            return result
        elif c1a == c1b:
            # Stacked
            h = (r2a-r1a+1) + (r2b-r1b+1)
            w = max(c2a-c1a+1, c2b-c1b+1)
            result = [[1]*w for _ in range(h)]
            for i in range(r2a-r1a+1):
                for j in range(c2a-c1a+1):
                    result[i][j] = frame1[i][j]
            for i in range(r2b-r1b+1):
                for j in range(c2b-c1b+1):
                    result[i + (r2a-r1a+1)][j] = frame2[i][j]
            return result
        else:
            # Diagonal - place side by side
            w = (c2a - c1a + 1) + (c2b - c1b + 1)
            h = max(r2a-r1a+1, r2b-r1b+1)
            result = [[1]*w for _ in range(h)]
            for i in range(r2a-r1a+1):
                for j in range(c2a-c1a+1):
                    result[i][j] = frame1[i][j]
            for i in range(r2b-r1b+1):
                for j in range(c2b-c1b+1):
                    result[i][j + (c2a-c1a+1)] = frame2[i][j]
            return result

def transform(grid: list[list[int]]) -> list[list[int]]:
    from collections import deque

    rows = len(grid)
    cols = len(grid[0])
    result = [[6]*cols for _ in range(rows)]
    visited = [[False]*cols for _ in range(rows)]

    # Find connected components of non-6 cells
    components = []
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] != 6 and not visited[i][j]:
                comp = []
                queue = deque([(i, j)])
                visited[i][j] = True
                while queue:
                    r, c = queue.popleft()
                    comp.append((r, c))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = r+dr, c+dc
                        if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc] and grid[nr][nc] != 6:
                            visited[nr][nc] = True
                            queue.append((nr, nc))
                components.append(comp)

    comp_sets = [set(c) for c in components]

    for idx, comp in enumerate(components):
        rmin = min(r for r, c in comp)
        rmax = max(r for r, c in comp)
        cmin = min(c for r, c in comp)
        cmax = max(c for r, c in comp)
        h = rmax - rmin + 1
        w = cmax - cmin + 1

        # Build sub-grid
        bbox = [[6]*w for _ in range(h)]
        for (r, c) in comp:
            bbox[r - rmin][c - cmin] = grid[r][c]

        # Identify 9-cap and content axis
        cap = None
        if all(bbox[0][j] == 9 for j in range(w)):
            cap = (0, 0, 1)       # horizontal, top
        elif all(bbox[h-1][j] == 9 for j in range(w)):
            cap = (0, 0, -1)      # horizontal, bottom
        elif all(bbox[i][0] == 9 for i in range(h)):
            cap = (1, 0, 1)       # vertical, left
        elif all(bbox[i][w-1] == 9 for i in range(h)):
            cap = (1, 0, -1)      # vertical, right

        if cap is None:
            # No clear cap, just place as-is
            for i in range(h):
                for j in range(w):
                    result[rmin+i][cmin+j] = bbox[i][j]
            continue

        axis, _, direction = cap

        # Determine content sub-rectangle (non-9 part)
        if axis == 0:
            if direction == 1:
                content_r0, content_r1 = 1, h-1
            else:
                content_r0, content_r1 = 0, h-2
            content_c0, content_c1 = 0, w-1
            c_rows = content_r1 - content_r0 + 1
            c_cols = w
        else:
            content_r0, content_r1 = 0, h-1
            if direction == 1:
                content_c0, content_c1 = 1, w-1
            else:
                content_c0, content_c1 = 0, w-2
            c_rows = h
            c_cols = content_c1 - content_c0 + 1

        # Content absolute position
        if axis == 0:
            cont_rmin = rmin + content_r0
            cont_rmax = rmin + content_r1
            cont_cmin = cmin + content_c0
            cont_cmax = cmin + content_c1
        else:
            cont_rmin = rmin + content_r0
            cont_rmax = rmin + content_r1
            cont_cmin = cmin + content_c0
            cont_cmax = cmin + content_c1

        # Compute max valid slide in the direction
        max_slide = 0
        for d in range(1, 50):
            valid = True
            for i in range(c_rows):
                for j in range(c_cols):
                    if axis == 0:
                        nr = cont_rmin + i + d * direction
                        nc = cont_cmin + j
                    else:
                        nr = cont_rmin + i
                        nc = cont_cmin + j + d * direction
                    if nr < 0 or nr >= rows or nc < 0 or nc >= cols:
                        valid = False
                        break
                    for oidx in range(len(components)):
                        if oidx != idx and (nr, nc) in comp_sets[oidx]:
                            valid = False
                            break
                    if not valid:
                        break
                if not valid:
                    break
            if not valid:
                max_slide = d - 1
                break
        else:
            max_slide = 49

        d = max_slide

        # Build output: place content at new position, 9s where they remain in original cap
        for i in range(c_rows):
            for j in range(c_cols):
                if axis == 0:
                    nr = cont_rmin + i + d * direction
                    nc = cont_cmin + j
                else:
                    nr = cont_rmin + i
                    nc = cont_cmin + j + d * direction
                result[nr][nc] = bbox[content_r0 + i][content_c0 + j]

        # Place 9s where they remain (original cap cells that didn't shift out)
        if axis == 0:
            for j in range(w):
                for k in range(h):
                    if bbox[k][j] == 9:
                        new_k = k + d * direction
                        if 0 <= new_k < h:
                            result[rmin + new_k][cmin + j] = 9
        else:
            for i in range(h):
                for j in range(w):
                    if bbox[i][j] == 9:
                        new_j = j + d * direction
                        if 0 <= new_j < w:
                            result[rmin + i][cmin + new_j] = 9

        # Convert N = min(d, num_5s) trailing 5s to 7s
        five_positions = []
        for i in range(c_rows):
            for j in range(c_cols):
                val = bbox[content_r0 + i][content_c0 + j]
                if val == 5:
                    if axis == 0:
                        five_positions.append((i, j, i * direction))
                    else:
                        five_positions.append((i, j, j * direction))
                    five_positions[-1] = (i, j, five_positions[-1][2])

        five_positions.sort(key=lambda x: (-x[2], x[0], x[1]))
        n_convert = min(d, len(five_positions))

        for k in range(n_convert):
            i, j, _ = five_positions[k]
            ci = content_r0 + i
            cj = content_c0 + j
            if axis == 0:
                nr = cont_rmin + i + d * direction
                nc = cont_cmin + j
            else:
                nr = cont_rmin + i
                nc = cont_cmin + j + d * direction
            result[nr][nc] = 7

    return result
